/**
 * Picklist authoring shapes — `PicklistConfigInput` (the polymorphic
 * static/dynamic config wrapper), its sub-shapes, and the
 * `PicklistValueExInput` value declaration record.
 *
 * Mirrors ultron's `PicklistConfigInput` (`shared/.../picklist/model/`)
 * with the deprecated `dynamicPicklistConfig` and internal `stage`
 * paths intentionally not surfaced — see comments on
 * `PicklistConfigInput`.
 */
import type { Filter } from "../../../../src/entities/shared/filters/types.js";
/** Free-form sort spec forwarded verbatim to ultron's `Sort` type. */
export type PicklistSortInput = Readonly<Record<string, unknown>>;
/**
 * How a dynamic picklist renders its values. Mirrors
 * `AspectDynamicPicklistValuesRenderType` on ultron — used to switch
 * between rendering the related record's display value vs. an icon
 * etc. depending on UI affordance.
 */
export type AspectDynamicPicklistValuesRenderType = string;
/**
 * Mirror of `PicklistDynamicParentMapping`
 * (`ultron/.../picklist/model/PicklistDynamicParentMapping.java`) —
 * pairs a parent-aspect field with a related-aspect field for cascading
 * picklists.
 */
export interface PicklistDynamicParentMapping {
    readonly parentAspectFieldId: string;
    readonly relatedAspectFieldId: string;
}
/**
 * Mirror of `PicklistStaticConfigInput`
 * (`ultron/.../picklist/model/PicklistStaticConfigInput.java`).
 * The values themselves come via `picklistValues` on the field — this
 * config carries optional filter/sort and parent linkage.
 */
export interface PicklistStaticConfigInput {
    readonly parentFieldId?: string;
    readonly filter?: Filter;
    readonly sort?: PicklistSortInput;
}
/**
 * Mirror of `PicklistDynamicConfigInput`
 * (`ultron/.../picklist/model/PicklistDynamicConfigInput.java`).
 * Configures a picklist whose values come from records of another
 * aspect — `relatedAspectId` is the source aspect, `relatedLabelFieldId`
 * is the field on that aspect whose value is shown for each option.
 */
export interface PicklistDynamicConfigInput {
    readonly relatedAspectId: string;
    readonly relatedLabelFieldId: string;
    readonly parentFieldId?: string;
    readonly parentMappings?: readonly PicklistDynamicParentMapping[];
    readonly autoRelate?: boolean;
    readonly valuesRenderType?: AspectDynamicPicklistValuesRenderType;
    readonly filter?: Filter;
    readonly sort?: PicklistSortInput;
}
/**
 * Mirror of `PicklistConfigInput`. Polymorphic — exactly one of
 * `static` or `dynamic` is populated; the platform dispatches on
 * the populated branch.
 *
 * `stage` and `api` are intentionally not exposed for authoring:
 *   - `stage` is internal-only (process-state picklists are
 *     auto-managed by the platform).
 *   - `api` (HTTP-sourced picklists) carries a sprawling shape
 *     (URL/body templates, auth, JSON Schema response, etc.) that
 *     deserves its own typed authoring contract — deferred to a
 *     follow-on piece. Authors needing API picklists today should
 *     wait for that work or open a feature request.
 */
export interface PicklistConfigInput {
    /** Static picklist — values are listed in `picklistValues`. */
    readonly static?: PicklistStaticConfigInput;
    /** Values come from records of another aspect. */
    readonly dynamic?: PicklistDynamicConfigInput;
}
/**
 * Mirror of `PicklistValueExInput` — the "new way" of declaring picklist
 * values. The EDK exposes only the canonical-id + label pair (the rest
 * of the wire shape is largely defaults the agent never sets).
 *
 * `relatedParentValues` carries the per-option dependent-picklist
 * mapping: each entry is an id of an option on this field's
 * `parentField`. Server-side validation rejects a record save whose
 * child selection's `relatedParentValues` doesn't contain the current
 * parent option's id. Names mirror the platform input (`relatedParentValues`
 * on write, returned as `parentPicklistValueIds` on read — the read
 * shape lives on {@link PicklistValue}).
 */
export interface PicklistValueExInput {
    readonly id?: string;
    readonly value: string;
    readonly label?: string;
    readonly color?: string;
    readonly icon?: string;
    readonly relatedParentValues?: readonly string[];
    /**
     * Per-value semantic tags — `CLOSED`, `CRITICAL`, `HIGH`, `MEDIUM`,
     * `LOW`. The platform reads these to drive behaviour on the STATUS
     * field (CLOSED-tagged values auto-stamp close timestamps) and to
     * surface priority hints in the UI. Round-trips through the pull
     * → re-deploy path; agents writing fresh status fields can set
     * `CLOSED` to mark which value represents a closed record.
     */
    readonly tags?: readonly string[];
}
